{
 'slug': 'landing-page',
 'category': 'homepage',
 'title': 'LP（ランディングページ）とは？ホームページとの違いと、費用の考え方',
 'description': 'LP（ランディングページ）とは何か、ホームページと何が違うのかを、中小企業向けにまとめました。LPが向いている場面と向いていない場面、入れておきたい6つの要素、費用が決まる要素と目安、作ったあとに必要なことを紹介します。',
 'date': '2026-10-10',
 'updated': '2026-10-17',
 'points': ['LPとは何か、ホームページとの違いと、メリット・デメリット', 'LPの作り方と、よく使われる構成の型', '費用が決まる要素と、公開後の改善（LPO・A/Bテスト）'],
 'body': '''
<p>ホームページの相談をしていると、「LPを作りませんか」と言われることがあります。広告の話でもよく出てくる言葉ですが、会社のホームページとどう違うのか、どちらを作ればいいのかは、分かりにくいところです。</p>
<p>この記事では、LPとは何か、メリットとデメリット、作り方と構成の型、費用は何で決まるのか、公開したあとにどう直していくのかを、制作する側の目線で紹介します。LPは、合う場面で使えば力を発揮しますが、作っただけでは人が来ない、という特徴もあります。その点も合わせてお伝えします。</p>

<h2 id="what">LP（ランディングページ）とは</h2>
<p>LPは「ランディングページ」を短くした呼び方です。もともとは、検索や広告から来た人が、最初に着地（ランディング）するページ、という意味の言葉です。</p>
<p>制作の現場では、もう少しせまい意味で使われています。<b>一つの目的のために、1枚で完結するように作った縦に長いページ</b>のことです。問い合わせ、資料請求、応募など、読んだ人にしてほしい行動を一つに決め、そこへ向かって上から順に読み進められるように作ります。</p>
<h3>広い意味と、せまい意味</h3>
<p>LPという言葉には、2つの使われ方があります。話がかみ合わないときは、どちらの意味で話しているかを確かめると、すっきりします。</p>
<table class="art-table">
<tr><th></th><th>広い意味のLP</th><th>せまい意味のLP</th></tr>
<tr><td>指すもの</td><td>訪れた人が最初に開いたページ</td><td>一つの目的のために作った1枚のページ</td></tr>
<tr><td>例</td><td>検索から直接開かれた、会社のホームページの「事業内容」のページ</td><td>広告の行き先として作った、問い合わせのためのページ</td></tr>
<tr><td>使われる場面</td><td>アクセスの数字を見るとき</td><td>制作の相談や見積りのとき</td></tr>
</table>
<p>アクセスを調べる道具では、広い意味で「ランディングページ」という言葉が使われます。どのページから見始めた人が多いか、という意味です。一方、制作会社が「LPを作りましょう」と言うときは、ほとんどがせまい意味です。この記事でも、ここから先はせまい意味のLPについてお話しします。</p>
<p>なお、音楽のレコード（LP盤）など、Webとは関係のない分野でも「LP」と略す言葉があります。Webの話をしているときは、ランディングページのことだと考えて差し支えありません。</p>

<h2 id="diff">ホームページとの違い</h2>
<table class="art-table">
<tr><th></th><th>LP</th><th>会社のホームページ</th></tr>
<tr><td>目的</td><td>一つの行動（問い合わせ・応募など）</td><td>会社の全体を伝える</td></tr>
<tr><td>ページ数</td><td>1ページ</td><td>複数のページ</td></tr>
<tr><td>読む人</td><td>広告やチラシなどから来た、関心のある人</td><td>取引先、求職者、金融機関など、いろいろな人</td></tr>
<tr><td>ほかのページへのリンク</td><td>少なくする</td><td>行き来しやすくする</td></tr>
<tr><td>主な入口</td><td>広告、SNS、チラシ、メール</td><td>検索、名刺、Googleマップ</td></tr>
</table>
<p>会社のホームページは、いろいろな人のいろいろな疑問に答える「会社案内」です。LPは、一つのサービスについて、一人の読む人に向けて書いた「提案書」に近いものです。どちらが上というものではなく、役目が違います。</p>

<h2 id="merit">LPのメリット・デメリット</h2>
<p>LPを作るかどうかを決める前に、良いところと苦手なところを並べてみましょう。</p>
<table class="art-table">
<tr><th>メリット</th><th>デメリット</th></tr>
<tr><td>伝えたいことを、決めた順番で読んでもらえる</td><td>検索では見つけてもらいにくい</td></tr>
<tr><td>読む人を迷わせず、問い合わせまで進んでもらいやすい</td><td>人を呼ぶ手だて（広告など）が別に必要になる</td></tr>
<tr><td>1ページなので、ホームページより早く公開できる</td><td>一つのサービスしか伝えられない</td></tr>
<tr><td>見た人の数と問い合わせの数を、比べやすい</td><td>公開後に直していかないと、成果が出にくい</td></tr>
<tr><td>文章や順番を直したときの変化が分かりやすい</td><td>構成と文章の出来で、成果が大きく変わる</td></tr>
</table>
<h3>メリット：迷わせずに、一つの行動へ案内できる</h3>
<p>会社のホームページでは、読む人が自分でページを選んで行き来します。知りたいことにたどり着けないまま、帰ってしまうこともあります。LPは、上から順に読むだけで、知りたいことが並ぶように作ります。途中でほかのページへ移らないので、伝える側が決めた順番どおりに読んでもらえます。</p>
<p>また、1ページで完結しているので、「何人が見て、何人が問い合わせたか」がはっきり分かります。どこを直せば良くなるかを考えやすいのも、LPの良いところです。</p>
<h3>デメリット：人を呼ぶ手間と、直す手間がかかる</h3>
<p>LPは、検索から人が集まりにくいページです。一つのサービスについて書いた1ページしかないので、探す人が使う、いろいろな言葉に応えきれないからです。広告やチラシなど、人を呼ぶ手だてを別に用意する必要があります。</p>
<p>もう一つは、作って終わりにしにくいことです。最初に作ったものが一番良い形とは限りません。見た人の反応を見ながら、言葉や順番を直していく前提で考えておくと、あとで困りません。</p>

<h2 id="fit">LPが向いている場面</h2>
<ul>
<li><b>広告を出すとき</b>：広告を見て来た人に、そのサービスの話だけを読んでもらえます。</li>
<li><b>一つのサービスや商品を、しっかり伝えたいとき</b>：新しく始めたサービス、力を入れたい商品などに向いています。</li>
<li><b>採用に力を入れたいとき</b>：求人の内容に合わせた、応募のためのページを作れます。採用ページの書き方は、<a href="../recruit-page/">採用ページで応募が増える書き方</a>で紹介しています。</li>
<li><b>展示会やチラシから、人を呼びたいとき</b>：QRコードの行き先として、内容を合わせたページを用意できます。</li>
<li><b>まず小さく始めたいとき</b>：会社のホームページを作る前に、1枚で会社とサービスを伝える使い方もあります。</li>
</ul>

<h2 id="ads">LPがWeb広告と相性がよい理由</h2>
<p>LPが一番使われているのは、検索やSNSの広告の行き先としてです。相性がよいのには、いくつか理由があります。</p>
<h3>広告の言葉と、ページの中身をそろえられる</h3>
<p>広告を押した人は、広告に書いてあったことの続きを知りたくて来ています。たとえば「試作1個から相談できます」という広告を押したのに、会社のトップページが開いて、試作の話がどこにあるか分からないと、多くの人はすぐに戻ってしまいます。LPなら、広告で伝えたことの続きを、最初の画面から書けます。</p>
<h3>広告の評価にも関わる</h3>
<p>Google広告では、広告の質を表す「品質スコア」の要素の一つに、「ランディングページの利便性」があります。広告を押した人にとって、行き先のページがどのくらい関係があり、役に立つかを見るものです。広告の内容に合ったページを用意しておくことは、読む人のためだけでなく、広告を出すうえでも大切です。</p>
<h3>広告ごとに、行き先を分けられる</h3>
<p>「新しい設備で対応できる加工」と「短い納期の相談」のように、伝えたいことが違う広告には、それぞれに合ったページを用意できます。一つのページで何もかも説明するより、来た人の関心に合わせやすくなります。</p>
<h3>広告費が成果につながったかを、確かめやすい</h3>
<p>広告から来た人が、LPを読んで問い合わせたかどうかを数えられます。広告にいくら使い、問い合わせが何件あったかが分かるので、広告を続けるか、やめるか、ページを直すかを判断しやすくなります。</p>
<p>反対に、広告の行き先を会社のトップページにしていると、問い合わせが広告から来たのか、ほかから来たのかが分かりにくくなります。広告を出す予定があるなら、行き先のページを一緒に考えるのがおすすめです。</p>

<h2 id="not-fit">LPだけでは足りない場面</h2>
<p>LPには、苦手なこともあります。</p>
<ul>
<li><b>検索で見つけてもらう</b>：1ページしかないため、いろいろな言葉で検索されたときに、出てきにくくなります。検索から人を呼びたい場合は、事業の内容ごとにページを分けたホームページのほうが向いています。</li>
<li><b>会社の全体を伝える</b>：会社概要、実績、採用など、見る人によって知りたいことが違う場合は、1枚に入りきりません。</li>
<li><b>情報を足していく</b>：お知らせや実績を足して育てていく使い方には、向いていません。</li>
</ul>
<p>また、取引先の会社では、LPを読んで興味を持ったあとに、「どんな会社か」を確かめるために会社のホームページを探すことがよくあります。そのときに会社の情報が見つからないと、問い合わせをためらわれることもあります。</p>
<p>会社のホームページがすでにあり、そこへLPを足す、という形が、多くの場合に使いやすい組み合わせです。ページ数の考え方は、<a href="../homepage-pages/">ホームページは何ページ必要？</a>で紹介しています。</p>

<h2 id="parts">LPに入れておきたい6つの要素</h2>
<p>LPの中身は、目的によって変わりますが、多くのLPに共通する要素があります。上から順に、読む人の気持ちの流れに合わせて並べるのが基本です。</p>
{{fig:lp}}
<h3>1. 最初の画面</h3>
<p>誰の、どんな困りごとに応えるページかを、ひと目で伝えます。ここで合わないと思われると、続きは読まれません。開いてすぐ、スクロールせずに見える部分には、次の3つを入れておくと伝わりやすくなります。</p>
<ul>
<li>誰に向けたページか（例：試作品の加工先を探している設計担当の方へ）</li>
<li>何ができるか、何が得られるか（例：図面1枚から、試作1個でも相談できます）</li>
<li>問い合わせのボタン</li>
</ul>
<p>雰囲気のある写真や、「品質への想い」のような抽象的な言葉だけでは、自分に関係があるかが判断できません。具体的な言葉を、短く書くのがコツです。</p>
<h3>2. 悩みへの共感</h3>
<p>読む人が困っていることを、具体的な言葉で書きます。「こんなことで困っていませんか」と、読む人が自分のことだと思える場面を並べます。普段の相談で、お客様が最初に口にすることを思い出すと、書きやすくなります。営業の担当者や、電話を受けている人に聞いてみるのもおすすめです。</p>
<h3>3. サービスの内容</h3>
<p>何を、どこまで、どのように行うかを書きます。対応できる量、地域、期間の目安など、相談してよいかを判断できる情報を入れます。できないことも書いておくと、合う相談が増えます。選ばれる理由（ほかとの違い）も、ここで具体的に伝えます。「丁寧」「安心」ではなく、何がどう違うのかを書きましょう。</p>
<h3>4. 実績・お客様の声</h3>
<p>実際の数字や事例を載せます。確かめられる内容だけを使います。取引先の名前を出せない場合は、業種、内容、規模などを書くだけでも、読む人は自分の場合に重ねて考えやすくなります。お客様の声を載せるときは、載せてよいか、どこまで書いてよいかを、必ず先に確かめておきます。</p>
<h3>5. よくある質問</h3>
<p>費用、期間、対応できる地域など、問い合わせの前に気になることに先に答えます。費用は、はっきりした金額が出せなくても、何で金額が決まるかや、依頼から納品までの流れを書いておくと、不安が減ります。</p>
<h3>6. 問い合わせの入口</h3>
<p>ボタンやフォームを、ページの途中と最後に置きます。入力する項目は、必要なものだけにします。「まずは相談だけでも」「資料だけ欲しい」など、気軽さに合わせた入口を用意すると、問い合わせの数が変わることがあります。送ったあとに何が起きるか（何日以内に返事をする、など）も書いておくと、安心して送ってもらえます。</p>
<h3>よく使われる並べ方の型</h3>
<p>LPの構成には、よく使われる流れがあります。名前のついた型もいくつかありますが、考え方はおおむね同じです。</p>
<ol>
<li><b>呼びかけ</b>：誰の、どんな困りごとに応えるかを伝える</li>
<li><b>問題</b>：読む人の悩みや、そのままにしたときに起きることを書く</li>
<li><b>解決</b>：その悩みを、どう解決できるかを示す</li>
<li><b>根拠</b>：実績、事例、数字、お客様の声で、信じてよい理由を示す</li>
<li><b>不安の解消</b>：費用、流れ、よくある質問に答える</li>
<li><b>行動</b>：問い合わせ、資料請求、応募などへ案内する</li>
</ol>
<p>取引先の会社に向けたLPでは、読む人が社内で上司に説明する場面もよくあります。根拠と不安の解消を厚くして、そのまま社内で共有できる情報をそろえておくと、話が進みやすくなります。</p>

<h2 id="flow">LPの作り方と、制作の流れ</h2>
<p>LPは1ページですが、作り方の順番はホームページとほぼ同じです。いきなりデザインから始めるのではなく、「誰に、何をしてほしいか」から決めていきます。</p>
<ol>
<li><b>目的を一つに決める</b>：問い合わせ、資料請求、応募、見学の申し込みなど、読んだ人にしてほしい行動を一つに決めます。</li>
<li><b>読む人を決める</b>：どんな立場の人が、どんなことに困って、このページを開くのかを考えます。</li>
<li><b>人を呼ぶ場所を決める</b>：検索広告、SNS、チラシ、展示会、メールなど、どこから来てもらうかを決めます。来る場所によって、最初の画面に書く言葉が変わります。</li>
<li><b>材料を集める</b>：実績、写真、お客様の声、よくある質問、料金の考え方などを集めます。</li>
<li><b>構成と文章を作る</b>：何をどの順番で伝えるかを決め、文章を書きます。LPの成果は、ここで大きく変わります。</li>
<li><b>デザインと作り込み</b>：文章が読みやすく、スマホでも見やすい形にします。</li>
<li><b>確認</b>：スマホとパソコンでの見え方、フォームから送ったメールが届くか、見た人の数や問い合わせを数える設定ができているかを確かめます。</li>
<li><b>公開と改善</b>：公開したあとは、数字を見ながら直していきます。</li>
</ol>
<p>マツケンスタジオでは、LPの制作期間は数週間から1か月ほどが目安です。材料がそろっているかどうかで、期間は変わります。写真と文章の準備については<a href="../homepage-photo-text/">ホームページに載せる写真と文章の用意のしかた</a>、全体の進み方は<a href="../homepage-flow/">ホームページ制作の流れと期間</a>で紹介しています。</p>
<h3>作る前に決めておきたいこと</h3>
<ul>
<li>どこに公開するか（会社のホームページの中か、別のアドレスか）</li>
<li>問い合わせが来たら、誰が、何日以内に返事をするか</li>
<li>公開後に、誰が数字を見て、誰が直すか</li>
</ul>
<p>特に、問い合わせへの返事の担当は見落とされがちです。せっかく問い合わせが来ても、返事が遅れると、ほかの会社に決まってしまうこともあります。</p>

<h2 id="cost">費用が決まる要素と、目安</h2>
<p>LPは1ページですが、費用には幅があります。同じ「LP制作」でも、どこまでを制作会社が行うかによって、中身がまったく違うからです。金額を左右するのは、主に次の4つです。</p>
<h3>1. 構成と文章を、誰が考えるか</h3>
<p>LPは、何をどの順番で伝えるかで成果が変わります。ここを任せるかどうかで、費用が大きく変わります。文章を自社で用意して、制作会社はデザインと作り込みだけを行う場合と、話を聞いて、構成から文章まで制作会社が考える場合とでは、かかる手間がまったく違います。広告の行き先にするなら、構成と文章は特に大切なところです。</p>
<h3>2. ページの長さ</h3>
<p>伝える内容が多いほど、作る量が増えます。はじめてその会社を知る人に向けたページや、検討に時間がかかるサービスのページほど、説明が多くなり、長くなります。</p>
<h3>3. 写真や図</h3>
<p>撮影をするか、図を新しく作るかで変わります。現場の写真、設備、製品、働く人など、実際の写真があると、伝わり方が大きく変わります。手元の写真を使うのか、撮影から頼むのかを、見積りの前に決めておきましょう。</p>
<h3>4. フォームなどの機能</h3>
<p>入力の項目が多い、ほかの仕組みとつなぐ、といった場合に増えます。予約や資料のダウンロード、問い合わせの内容を社内の仕組みに送るなど、機能が増えるほど、作る手間と確かめる手間がかかります。</p>
<p>マツケンスタジオでは、1枚で完結するページの制作は15万円から、期間は数週間から1か月ほどが目安です。くわしくは<a href="../../lp/">LP制作のページ</a>をご覧ください。費用の考え方は、<a href="../homepage-cost/">ホームページ制作の費用は何で決まる？</a>でも紹介しています。</p>
<p>制作費のほかに、広告を出す場合は広告費が、別のドメインやサーバーで公開する場合はその費用がかかります。見積りを取るときは、制作費に何が含まれているかを確かめましょう。</p>
<h3>見積りで確かめたいこと</h3>
<ul>
<li>構成と文章は、どちらが用意するか</li>
<li>写真や図は、誰が用意するか</li>
<li>スマホでの見え方の調整は含まれているか</li>
<li>見た人の数や問い合わせを数える設定は含まれているか</li>
<li>公開後の修正は、何回まで、いくらでできるか</li>
<li>ドメインやサーバーは、誰の名義になるか</li>
</ul>
<p>相場の金額だけで比べると、中身が違うものを比べてしまうことがあります。見積りの見方は<a href="../estimate-check/">ホームページの見積りの見方</a>で紹介しています。</p>

<h2 id="after">作っただけでは、人は来ない</h2>
<p>LPで一番気をつけたいのは、<b>作っただけでは見てもらえない</b>ことです。検索では見つけてもらいにくいので、人を呼ぶ手だてを一緒に考える必要があります。</p>
<ul>
<li>検索やSNSの広告を出す</li>
<li>チラシ、名刺、展示会の資料にQRコードを載せる</li>
<li>会社のホームページから、リンクを張る</li>
<li>これまでのお客様に、メールやはがきで案内する</li>
</ul>
<p>公開したあとは、どのくらいの人が見て、どのくらい問い合わせにつながったかを確かめ、最初の画面の言葉やボタンの位置を直していきます。LPは、公開してから手を入れていくことで、少しずつ成果が出るようになるページです。</p>

<h2 id="improve">公開後の改善：LPOとA/Bテスト</h2>
<p>LPを直していく取り組みを、「LPO」と呼ぶことがあります。ランディングページを、より成果が出るように良くしていく、という意味の言葉を短くしたものです。難しく聞こえますが、やることは「数字を見て、直して、また数字を見る」の繰り返しです。</p>
<h3>まず見る数字</h3>
<table class="art-table">
<tr><th>見る数字</th><th>分かること</th></tr>
<tr><td>見た人の数</td><td>広告やチラシから、どのくらい人が来ているか</td></tr>
<tr><td>問い合わせの数</td><td>ページを読んで、行動まで進んだ人の数</td></tr>
<tr><td>問い合わせの割合</td><td>見た人のうち、何人に1人が問い合わせたか</td></tr>
<tr><td>どこまで読まれたか</td><td>ページのどのあたりで、読むのをやめた人が多いか</td></tr>
</table>
<p>見た人が少ないなら、ページより先に、人を呼ぶ手だてを見直します。見た人はいるのに問い合わせが少ないなら、ページの中身を直します。数字の確かめ方は、<a href="../no-inquiry/">ホームページから問い合わせが来ない理由</a>でも紹介しています。</p>
<h3>直す順番</h3>
<ol>
<li><b>最初の画面</b>：多くの人がここで読むのをやめるので、一番効果が出やすいところです。</li>
<li><b>問い合わせの入口</b>：ボタンの言葉、置く場所、フォームの項目の数を見直します。</li>
<li><b>根拠と、よくある質問</b>：途中でやめる人が多いなら、不安に答える情報が足りないのかもしれません。</li>
</ol>
<h3>A/Bテストとは</h3>
<p>A/Bテストは、一部だけを変えた2つの案（AとB）を用意して、来た人に振り分けて見せ、どちらが問い合わせにつながりやすいかを比べる方法です。たとえば、最初の画面の見出しだけを変えた2つのページを用意し、半分ずつの人に見せます。</p>
<p>A/Bテストで気をつけたいのは、次の3つです。</p>
<ul>
<li><b>一度に変えるのは一か所だけ</b>：いくつも変えると、どれが効いたのか分からなくなります。</li>
<li><b>見た人が少ないうちは、結果がぶれる</b>：数十人ほどの差では、たまたまの差のこともあります。ある程度の人数が集まるまで待ちます。</li>
<li><b>期間をそろえる</b>：曜日や時期によって、来る人が変わることがあります。2つの案は、同じ期間に比べます。</li>
</ul>
<p>見た人がまだ少ない場合は、A/Bテストにこだわらなくても大丈夫です。問い合わせをくれたお客様に、どこを読んで決めたかを聞いたり、営業でよく受ける質問をページに足したりするだけでも、十分な改善になります。</p>
<p>LPを自分たちで直すのが難しい場合は、制作会社に続けて見てもらう方法もあります。マツケンスタジオでは、最初の相談から公開後まで同じ担当がつき、公開後の更新や改善も続けられます。</p>

<h2 id="summary">まとめ</h2>
<p>LPは、一つの目的のために作る、1枚で完結するページです。広告やチラシから来た人に、一つのサービスをしっかり伝えるのに向いていて、Web広告の行き先として特に力を発揮します。一方で、検索で見つけてもらうことや、会社の全体を伝えることは苦手です。</p>
<p>作るときは、目的と読む人を決め、最初の画面、悩みへの共感、サービスの内容、実績、よくある質問、問い合わせの入口を順に並べます。費用は、構成と文章を誰が考えるか、ページの長さ、写真や図、機能で変わります。公開したあとは、数字を見ながら最初の画面や入口を直していきましょう。「誰に、何をしてほしいか」と「どこから人を呼ぶか」が決まっているなら、LPは良い選択になります。</p>
''',
 'faq': [
  ('会社のホームページがなくても、LPだけ作れますか？', '作れます。まず1枚で会社とサービスを伝え、あとからページを足して、会社のホームページに育てていく進め方もあります。ただ、取引先の会社は、LPを読んだあとに会社の情報を確かめることが多いので、会社概要や所在地はLPの中にも載せておきましょう。'),
  ('LPとホームページは、どちらを先に作るべきですか？', '検索や名刺から来た人に会社を知ってもらいたいなら、ホームページが先です。広告を出す予定がある、一つのサービスを早く伝えたい、という場合は、LPから始めるのが合っています。'),
  ('LPは、どのくらいの長さが必要ですか？', '決まった長さはありません。読む人が問い合わせの前に知りたいことに、すべて答えられる長さが目安です。はじめて知る人に向けたページほど、長くなります。'),
  ('LPは、自分たちで更新できますか？', '作り方によります。文章や写真を自分たちで直せる作りにすることもできます。公開後に直しながら育てていくページなので、直し方と費用を、作る前に確かめておきましょう。'),
  ('LPOとは何ですか？', 'ランディングページを、より成果が出るように直していく取り組みのことです。見た人の数と問い合わせの数を見て、最初の画面や問い合わせの入口などを直し、また数字を確かめる、という繰り返しが中心です。'),
  ('LP制作の相場はいくらですか？', '構成や文章を誰が考えるか、ページの長さ、写真や図、フォームなどの機能によって大きく変わるため、一つの金額では言えません。見積りを比べるときは、金額だけでなく、何が含まれているかをそろえて比べましょう。マツケンスタジオでは、1ページのLPは15万円からが目安です。'),
 ],
},
