  ('今の管理費が高いと感じます。どうすればいいですか？', 'まず、管理費の中に何が含まれているかと、ドメイン代とサーバー代の実費がいくらかを、今の制作会社に聞いてみましょう。頼んでいる作業と合わない場合は、プランの見直しや、管理を任せる先を変える方法があります。'),
