  ('ホームページの維持費は、経費にできますか？', 'ドメイン代、サーバー代、保守の作業費など、使い続けるための費用は、一般に払った年の経費として扱われることが多い費用です。前払いの扱いや制作費の扱いは会社の状況で変わるので、顧問の税理士に確かめてください。'),
  ('維持費に補助金は使えますか？', '制作や作り直しの費用は、補助金の対象になることがあります。毎月の維持費が対象になるかは制度によって違うので、申請の前に公募要領で確かめましょう。'),
